def hcaptcha_ok(token, ip):
    if not (HC_SITE and HC_SECRET): return True
    if not token: return False
    try:
        data = urllib.parse.urlencode({"secret": HC_SECRET, "response": token, "remoteip": ip, "sitekey": HC_SITE}).encode()
        with urllib.request.urlopen(urllib.request.Request("https://api.hcaptcha.com/siteverify", data=data), timeout=15) as r:
            return bool(json.loads(r.read().decode()).get("success"))
    except Exception:
        return False
SECRET = hashlib.sha256((PASSWORD + "|aw").encode()).digest()
ALLOWED = {"sell", "unlist", "equip", "unequip", "stash", "unstash", "salvage", "identify", "discard", "deposit", "withdraw", "abyss", "talent", "requisition", "buy"}

def api(acct, method, path, body=None):
    data = json.dumps(body).encode() if body is not None else None
    req = urllib.request.Request(BASE + path, data=data, method=method, headers={
        "Authorization": "Bearer " + KEYS[acct], "Content-Type": "application/json", "User-Agent": "aw-panel/1"})
    for i in range(4):
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, json.loads(r.read().decode() or "{}")
        except urllib.error.HTTPError as e:
            txt = e.read().decode(errors="ignore")
            try: d = json.loads(txt)
            except Exception: d = {"error": txt[:300]}
            if e.code in (429, 502, 503, 504) and i < 3:
                time.sleep(min(float(d.get("retry_after", 3) or 3), 15)); continue
            return e.code, d
        except Exception as e:
            if i < 3: time.sleep(2); continue
            return 0, {"error": str(e)}

GRADE_CACHE = {}  # (acct, hero_id) -> grade; grades never change
GRADE_BUSY = set()
def _grade_fill(acct, need):
    try:
        for i in need:
            for _ in range(3):
                if (acct, i) in GRADE_CACHE: break
                try:
                    c, d = api(acct, "GET", "/world/me?unit=%d" % i)
                    hh = ((d.get("me") or {}).get("hero") or {}) if c == 200 else {}; g = hh.get("grade") or ("lord" if hh.get("kind") == "demon_lord" else None)
                    if g: GRADE_CACHE[(acct, i)] = g; break
                except Exception: pass
                time.sleep(1.5)
            time.sleep(0.4)
    finally:
        GRADE_BUSY.discard(acct)
def unit_grades(acct, ids):
    need = [i for i in ids if (acct, i) not in GRADE_CACHE]
    if need and acct not in GRADE_BUSY:
        GRADE_BUSY.add(acct); threading.Thread(target=_grade_fill, args=(acct, need), daemon=True).start()
    return {i: GRADE_CACHE.get((acct, i)) for i in ids}
# WALLETS 来自 keys.json（每个账号可选 wallet，用于宝箱卡查询未提取分红）
POOL = {}; PRICE = {}; POOL_BUSY = set()
def _get_json(url):
    with urllib.request.urlopen(urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"}), timeout=20) as r:
        return json.loads(r.read().decode())
def _pool_fill(acct):
    try:
        d = _get_json("https://boltbook.fun/api/v1/world/pool/claim?wallet=" + WALLETS[acct])
        POOL[acct] = (time.time(), {c.get("asset"): c.get("amount") for c in d.get("claims", [])})
    except Exception: pass
    try:
        if time.time() - PRICE.get("t", 0) > 300:
            x = _get_json("https://api.dexscreener.com/latest/dex/tokens/0xBbDd8C7720d1EEB1d63738eaABB584a4b72C7777")
            pr = sorted(x.get("pairs") or [], key=lambda q: -float((q.get("liquidity") or {}).get("usd") or 0))
            if pr:
                PRICE["bolt"] = float(pr[0]["priceUsd"]); pn = float(pr[0].get("priceNative") or 0)
                if pn and (pr[0].get("quoteToken") or {}).get("symbol") in ("WBNB", "BNB"): PRICE["bnb"] = PRICE["bolt"] / pn
            if "bnb" not in PRICE:
                PRICE["bnb"] = float(_get_json("https://api.binance.com/api/v3/ticker/price?symbol=BNBUSDT")["price"])
            PRICE["t"] = time.time()
    except Exception: pass
    POOL_BUSY.discard(acct)
def pool_info(acct):
    if acct not in WALLETS: return None
    t, v = POOL.get(acct, (0, None))
    if time.time() - t > 120 and acct not in POOL_BUSY:
        POOL_BUSY.add(acct); threading.Thread(target=_pool_fill, args=(acct,), daemon=True).start()
    return v
def slim_me(m):
    keys = ["name", "level", "xp", "xp_next", "hp", "max_hp", "ap", "ap_max", "next_ap_at", "coins", "power",
            "squad_power", "gear_score", "worn", "bag", "gear_bag", "gear_bag_max", "stash", "stash_max", "currencies",
            "x", "y", "ring", "food", "attack", "defense", "crit"]
    o = {k: m.get(k) for k in keys}
    h = m.get("hero") or {}
    o["hero"] = {"kind": h.get("kind"), "rank": h.get("rank"), "title": h.get("title"), "squad": h.get("squad"),
                 "path": (h.get("path") or {}).get("name"), "grade": h.get("grade"), "role": h.get("role")}
    o["in_camp"] = m.get("ring") == "camp"
    tl = m.get("talents") if isinstance(m.get("talents"), dict) else {}; o["talent_points"] = tl.get("points") or 0; o["paragon_points"] = tl.get("paragon_points") or 0
    f = m.get("falcon") if isinstance(m.get("falcon"), dict) else {}; e = m.get("envoy") if isinstance(m.get("envoy"), dict) else {}
    o["pets"] = [p for p in ([{"k": "falcon", "food": f.get("food"), "hungry": f.get("hungry")}] if f else []) + ([{"k": "lion", "food": e.get("food"), "hungry": e.get("hungry")}] if e and e.get("food") is not None else [])]
    o["bounties"] = m.get("bounties") or []; o["camp_orders"] = m.get("camp_orders") or []
    pz = m.get("prize") or {}
    o["chest"] = pz.get("chest"); o["chest_since"] = pz.get("chest_since"); o["run_from"] = pz.get("run_from")
    o["deeds_today"] = pz.get("deeds_today"); o["deeds_cap"] = pz.get("deeds_cap") or (m.get("hero") or {}).get("deeds_cap"); o["deeds_banked"] = pz.get("deeds_banked")
    return o

