def daily_runs(acct, un=""):
    import time as _t, threading
    k = (acct, un); hit = _DR.get(k)
    if hit and _t.time() - hit[0] < 60: return hit[1]
    r = {}
    def ab():
        c, d = api(acct, "GET", "/world/abyss" + ("?unit=" + un if un else ""))
        y = (d or {}).get("you") or {} if c == 200 else {}
        if not un:  # main only: can a node be lit with the cinder held? (red dot)
            c2, d2 = api(acct, "POST", "/world/act", {"action": "abyss", "do": "talents"}); t = (d2 or {}).get("talents") or {} if c2 == 200 else {}
            op = [x.get("cost") or 0 for x in (t.get("open") or [])]; r["abyss_can"] = bool(op) and (t.get("cinder") or 0) >= min(op)
        if "runs_left" in y: r["abyss_left"] = 1 if (y.get("runs_left") or 0) > 0 else 0; r["abyss_max"] = 1
    def fg():
        c, d = api(acct, "GET", "/world/fog")
        y = (d or {}).get("you") or {} if c == 200 else {}
        if "went_today" in y: r["fog_left"] = 0 if y.get("went_today") else 1; r["fog_max"] = 1
    ts = [threading.Thread(target=f) for f in (ab, fg)]; [t.start() for t in ts]; [t.join(25) for t in ts]
    _DR[k] = (_t.time(), r); return r

def market(acct):
    c, mine = api(acct, "GET", "/world/market/mine")
    trades, before = [], None
    for _ in range(3):  # 最近 150 笔成交
        q = "/world/market/trades?seller=" + acct + ("&before=%s" % before if before else "")
        c2, t = api(acct, "GET", q)
        if c2 != 200: break
        trades += t.get("trades", [])
        before = t.get("next_before")
        if not before or len(t.get("trades", [])) < 50: break
    trades = [t for t in trades if t.get("seller") == acct]
    return {"listings": mine.get("listings", []), "bids": mine.get("bids", []), "trades": trades}

