def token_ok(h):
    if not PASSWORD: return True
    ck = h.headers.get("Cookie", "")
    for part in ck.split(";"):
        k, _, v = part.strip().partition("=")
        if k == "awp" and hmac.compare_digest(v, hmac.new(SECRET, b"ok", hashlib.sha256).hexdigest()):
            return True
    return False

