class H(BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def send(self, code, body, ctype="application/json; charset=utf-8", extra=None):
        b = body if isinstance(body, bytes) else (body if isinstance(body, str) else json.dumps(body, ensure_ascii=False)).encode()
        self.send_response(code); self.send_header("Content-Type", ctype); 
        if "Cache-Control" not in (extra or {}): self.send_header("Cache-Control", "no-store")
        for k, v in (extra or {}).items(): self.send_header(k, v)
        self.end_headers(); self.wfile.write(b)
    def do_GET(self):
        u = urlparse(self.path); q = parse_qs(u.query)
        if u.path == "/bg.jpg":
            try: return self.send(200, open(os.path.join(HERE, "bg.jpg"), "rb").read(), "image/jpeg", {"Cache-Control": "max-age=86400"})
            except Exception: return self.send(404, b"", "text/plain")
        if not token_ok(self):
            return self.send(200, LOGIN, "text/html; charset=utf-8") if u.path == "/" else self.send(401, {"error": "login"})
        if u.path == "/": return self.send(200, PAGE, "text/html; charset=utf-8")
        acct = (q.get("acct") or [""])[0]
        if acct not in ACCTS and u.path.startswith("/api/") and u.path != "/api/accts":
            return self.send(400, {"error": "bad account"})
        if u.path == "/api/accts": return self.send(200, {"accts": ACCTS})
        if u.path == "/api/state":
            un = (q.get("unit") or [""])[0]
            c, d = api(acct, "GET", "/world/me" + ("?unit=" + un if un.isdigit() else ""))
            if c != 200: return self.send(c or 502, d)
            o = slim_me(d.get("me", {})); o.update(daily_runs(acct, un if un.isdigit() else ""))
            o["pool"] = pool_info(acct); o["prices"] = {k: PRICE.get(k) for k in ("bnb", "bolt")}
            return self.send(200, o)
        if u.path == "/api/mkt":
            qq = {k: (q.get(k) or [""])[0] for k in ("type", "goods", "slot", "rarity", "sort", "cursor")}
            qs = "&".join("%s=%s" % (k, urllib.parse.quote(v)) for k, v in qq.items() if v and re.fullmatch(r"[a-z0-9_]{1,40}", v))
            c, d = api(acct, "GET", "/world/market" + ("?" + qs if qs else ""))
            if c != 200: return self.send(c or 502, d)
            c2, d2 = api(acct, "GET", "/world/me"); m = (d2 or {}).get("me") or {}
            d["coins"] = m.get("coins"); d["in_camp"] = m.get("ring") == "camp"; d.pop("trades", None)
            return self.send(200, d)
