            us = {x.get("hero"): x for x in (m.get("units") or [])}; mh = (m.get("hero") or {}).get("id")
            tp = (d.get("temper") or {}).get("heroes") or []
            gr = unit_grades(acct, [h.get("hero") for h in tp if isinstance(h.get("hero"), int) and h.get("hero") in us])
            for h in tp:
                x = us.get(h.get("hero")) or {}; h["level_hero"] = x.get("level"); h["grade"] = gr.get(h.get("hero")); h["main"] = h.get("hero") == mh; h["unit"] = bool(x)
            d["main_hero"] = mh; d["in_camp"] = m.get("ring") == "camp"; d["ring"] = m.get("ring")
