            if tag:
                c2, tr = api(acct, "GET", "/world/tribes/" + tag); tr = (tr.get("tribe") or tr) if c2 == 200 else {}
                o["tstore"] = {"goods": tr.get("store") or {}, "slots": tr.get("store_slots") or {}, "rights": t.get("store_rights")}
